/**
 * Title/name normalization, ported verbatim from the legacy tool's
 * Fold-Text / Clean-Title / Norm-Title / Safe-Name / Is-AltVersion.
 *
 * Every rule exists because omitting it silently produced duplicates or
 * mismatches. Golden fixtures (generated by running the legacy PowerShell
 * implementation) pin the exact behavior in test/fixtures/.
 */

const DASH_RX = /[\u2010\u2011\u2012\u2013\u2014\u2015]/g;
const SINGLE_QUOTE_RX = /[\u2018\u2019\u201B]/g;
const DOUBLE_QUOTE_RX = /[\u201C\u201D]/g;

/**
 * Trailing release-variant labels. Anchored on " - " so real titles survive:
 * "Live Wire", "Live and Let Die", "White Wedding - Pt. 1".
 */
export const VERSION_RX =
  /\s*-\s*.*\b(re-?master(ed)?|re-?mix|\d{4}\s+mix|live|demo|single|edit|version|mono|stereo|radio|acoustic|take|session|anniversary|edition|soundtrack|recording|original music|from\s+")(?:\b)?.*$/gi;

/** Parenthetical/bracketed segments, including surrounding whitespace. */
const PAREN_RX = /\s*[([][^)\]]*[)\]]\s*/g;

/** Folds visually-identical punctuation to ASCII and trims. */
export function foldText(s: string | null | undefined): string {
  if (!s) return "";
  return s.replace(DASH_RX, "-").replace(SINGLE_QUOTE_RX, "'").replace(DOUBLE_QUOTE_RX, '"').trim();
}

/** Display title with trailing version labels removed ("X - 2019 Remaster" -> "X"). */
export function cleanTitle(s: string): string {
  return foldText(s).replace(VERSION_RX, "").trim();
}

/**
 * The dedup key: fold -> strip parentheticals -> strip version suffixes ->
 * strip diacritics (NFD + NonSpacingMark) -> lowercase alnum only.
 */
export function normTitle(s: string | null | undefined): string {
  if (!s) return "";
  let x = foldText(s).replace(PAREN_RX, " ");
  x = x.replace(VERSION_RX, "");
  const d = x.normalize("NFD").replace(/\p{Mn}/gu, "");
  return d
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]/g, "");
}

/** Strips characters forbidden in Windows paths (AC/DC -> AC-DC). */
export function safeName(s: string): string {
  return s
    .replace(/[\\/:*?"<>|]/g, "-")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\.+$/, "");
}

const ALT_PATTERNS = [
  /[([]\s*live\b/i,
  /\s-\s*live\b/i,
  /[([]\s*(demo|rehearsal|instrumental|karaoke|cover|remix)\b/i,
  /\bmedley\b/i,
];

/** True for live/demo/remix/karaoke/cover/medley variants we never want. */
export function isAltVersion(s: string): boolean {
  return ALT_PATTERNS.some((rx) => rx.test(s));
}
